 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(18));if(stroke!=0)d.setStroke(dp(2),stroke);return d;}
